package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

// ---------- record types and working storage ----------

type SalesRec struct { // 01 SALES-REC, 12 bytes
	SrId    string          // PIC X(4) @0 len=4
	SrSales decimal.Decimal // PIC 9(6)V99 @4 len=8
}

type TierTableEntry struct {
	TierLimit decimal.Decimal // PIC 9(6)V99 len=8
	TierRate  decimal.Decimal // PIC 9V99 len=3
}

var TierTable [4]TierTableEntry

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string = "N"
var WsIdx int64 = 0
var WsTier int64 = 0
var WsComm decimal.Decimal = decimal.Zero
var WsTotal decimal.Decimal = decimal.Zero
var WsCount int64 = 0
var WsSalesEd string // PIC ZZZ,ZZ9.99 len=10
var WsRateEd string  // PIC 9.99 len=4
var WsCommEd string  // PIC ZZZ,ZZ9.99 len=10
var WsTotalEd string // PIC ZZZ,ZZZ,ZZ9.99 len=14

// file buffer
var salesFileLines []string
var salesFilePos int
var SalesRecVar SalesRec

func isInputDone() bool {
	return WsEofFlag == "Y"
}
func setInputDone(v bool) {
	if v {
		WsEofFlag = "Y"
	} else {
		WsEofFlag = "N"
	}
}

// ---------- helpers ----------

func mustDecimal(s string, scale int32) decimal.Decimal {
	// s is integer string possibly with sign, scale = number of implied decimal places
	// Use NewFromString with shift? Use decimal.NewFromString and shift
	// Parse as integer then shift
	neg := false
	if strings.HasPrefix(s, "-") {
		neg = true
		s = s[1:]
	}
	// remove leading zeros but keep at least one
	d, err := decimal.NewFromString(s)
	if err != nil {
		d = decimal.Zero
	}
	d = d.Shift(-scale)
	if neg {
		d = d.Neg()
	}
	return d
}

func formatZZEdited(val decimal.Decimal, pic string) string {
	// pic contains Z,9,',','.'
	// width = len(pic)
	// Determine fractional placeholder count
	dotIdx := strings.Index(pic, ".")
	var intPic, fracPic string
	if dotIdx >= 0 {
		intPic = pic[:dotIdx]
		fracPic = pic[dotIdx+1:]
	} else {
		intPic = pic
		fracPic = ""
	}
	// count placeholders in frac
	fCount := 0
	for _, ch := range fracPic {
		if ch == 'Z' || ch == '9' {
			fCount++
		}
	}
	// Quantize val to fCount fractional digits (truncate toward zero is not needed for display? MOVE truncates? but scale matches)
	// For edited formatting, if more decimals than pic, they are truncated? We'll round? COBOL MOVE truncates? Actually moving numeric to edited truncates? We'll just round to fCount using Truncate toward zero.
	// Use Truncate to mimic COBOL store without rounding unless ROUNDED; but for display MOVE, it just aligns.
	// We'll truncate toward zero.
	q := val.Truncate(int32(fCount))
	// For negative, keep sign outside? Not needed.
	sign := ""
	if q.Sign() < 0 {
		sign = "-"
		q = q.Neg()
	}
	sFixed := q.StringFixed(int32(fCount))
	var intStr, fracStr string
	if fCount > 0 {
		parts := strings.SplitN(sFixed, ".", 2)
		intStr = parts[0]
		if len(parts) > 1 {
			fracStr = parts[1]
		} else {
			fracStr = strings.Repeat("0", fCount)
		}
		// ensure fracStr length fCount
		if len(fracStr) < fCount {
			fracStr = fracStr + strings.Repeat("0", fCount-len(fracStr))
		} else if len(fracStr) > fCount {
			fracStr = fracStr[:fCount]
		}
	} else {
		intStr = sFixed
		// remove any decimal part
		if idx := strings.Index(intStr, "."); idx >= 0 {
			intStr = intStr[:idx]
		}
		fracStr = ""
	}
	// intStr is digits without sign
	// count integer placeholders
	intPlaceCount := 0
	for _, ch := range intPic {
		if ch == 'Z' || ch == '9' {
			intPlaceCount++
		}
	}
	// handle integer digits overflow / pad
	// intStr may have leading zeros? It is numeric string without commas.
	// Remove sign already.
	if intStr == "" {
		intStr = "0"
	}
	if len(intStr) > intPlaceCount {
		intStr = intStr[len(intStr)-intPlaceCount:]
	} else if len(intStr) < intPlaceCount {
		intStr = strings.Repeat("0", intPlaceCount-len(intStr)) + intStr
	}
	// Build integer part chars
	intChars := []rune(intPic) // will be overwritten for placeholders with digits; commas stay
	// Need mapping placeholder index -> digit
	digitIdx := 0
	// Fill placeholders with digits
	for i, ch := range intChars {
		if ch == 'Z' || ch == '9' {
			intChars[i] = rune(intStr[digitIdx])
			digitIdx++
		}
	}
	// Zero suppression for Z
	suppressed := true
	for i, pch := range intPic {
		c := intChars[i]
		if pch == 'Z' {
			if suppressed && c == '0' {
				intChars[i] = ' '
			} else {
				suppressed = false
			}
		} else if pch == '9' {
			suppressed = false
		} else if pch == ',' {
			if suppressed {
				intChars[i] = ' '
			} else {
				intChars[i] = ','
			}
		} else {
			// '.' not in intPic
		}
	}
	result := string(intChars)
	if dotIdx >= 0 {
		result += "."
		// build fractional part: map fracPic placeholders to fracStr digits
		fracChars := []rune(fracPic)
		dIdx := 0
		for i, ch := range fracChars {
			if ch == 'Z' || ch == '9' {
				if dIdx < len(fracStr) {
					fracChars[i] = rune(fracStr[dIdx])
					dIdx++
				} else {
					fracChars[i] = '0'
				}
			}
		}
		// Fractional Z suppression not needed for given pics (they are 9s)
		// If there were Z in fraction, similar rules but not needed.
		result += string(fracChars)
	}
	// If sign, inject? For positive, nothing. For negative, conventionally replaces leading space with '-'?
	// Not needed for this program (all positive).
	if sign != "" {
		// place minus at leftmost space or prepend
		// Simple: replace first space from left with '-'; if none, prepend (but width would overflow)
		runes := []rune(result)
		placed := false
		for i := len(runes) - 1; i >= 0; i-- {
			if runes[i] == ' ' {
				// Find leftmost? Actually COBOL puts sign at first non-space? Simplify.
			}
		}
		_ = placed
		result = sign + result
		// Truncate/pad to width
		if len(result) > len(pic) {
			result = result[len(result)-len(pic):]
		}
	}
	// Ensure exact width = len(pic)
	if len(result) < len(pic) {
		// This can happen if intPic+dot+fracPic length != len(pic)? But dot included.
		// len(pic) includes dot already.
		result = strings.Repeat(" ", len(pic)-len(result)) + result
	}
	return result
}

func formatNumericUneditedInt(val int64, digits int) string {
	s := fmt.Sprintf("%d", val)
	if s[0] == '-' {
		// keep sign and zero pad after sign?
		num := s[1:]
		if len(num) > digits {
			num = num[len(num)-digits:]
		} else if len(num) < digits {
			num = strings.Repeat("0", digits-len(num)) + num
		}
		return "-" + num
	}
	if len(s) > digits {
		s = s[len(s)-digits:]
	} else if len(s) < digits {
		s = strings.Repeat("0", digits-len(s)) + s
	}
	return s
}

// COBOL-like storage for pictured numeric fields:
// PIC 9(6)V99 => 8 digits, scale 2, truncate and keep low-order digits
func storePic9V99(val decimal.Decimal, intDigits int, scale int32) decimal.Decimal {
	// Truncate toward zero to scale
	t := val.Truncate(scale)
	// Keep low-order digits if overflow: total digits = intDigits+scale
	// This corresponds to keeping val modulo 10^(intDigits+scale) /10^scale ?
	// For positive, we can compute integer scaled value then mod.
	totalDigits := int64(intDigits) + int64(scale)
	// scaled integer = t *10^scale  (truncated integer)
	scaled := t.Shift(scale) // e.g., 1234.56 *100 =123456
	// For negative, need to keep sign
	sign := scaled.Sign()
	if sign < 0 {
		scaled = scaled.Neg()
	}
	// Compute modulus =10^totalDigits
	mod := decimal.NewFromInt(1).Shift(int32(totalDigits)) // 10^totalDigits
	// Low-order digits: scaled mod mod
	// scaled is integer decimal (scale 0)
	// Use DivMod? Use Mod
	// decimal.Mod not sign correct? Use rem = scaled.Mod(mod)
	rem := scaled.Mod(mod)
	// Re-apply scale and sign
	result := rem.Shift(-scale)
	if sign < 0 {
		result = result.Neg()
	}
	return result
}

// ---------- file I/O ----------

func loadSalesFile() {
	data, err := os.ReadFile("input.dat")
	if err != nil {
		// no file => empty
		salesFileLines = []string{}
		return
	}
	// LINE SEQUENTIAL: split by lines (\n, \r\n)
	// Keep empty lines? Each line is a record
	content := string(data)
	// Use scanner to preserve behavior of lines without trailing newline
	var lines []string
	scanner := bufio.NewScanner(strings.NewReader(content))
	// Increase buffer
	buf := make([]byte, 0, 1024*1024)
	scanner.Buffer(buf, 10*1024*1024)
	for scanner.Scan() {
		lines = append(lines, scanner.Text())
	}
	// If file ends with newline, scanner will not produce extra empty line; COBOL would not have extra record.
	salesFileLines = lines
	salesFilePos = 0
}

func padRight(s string, n int) string {
	if len(s) >= n {
		return s[:n]
	}
	return s + strings.Repeat(" ", n-len(s))
}

func parseSalesRec(raw string) SalesRec {
	// pad to 12
	rec := padRight(raw, 12)
	srId := rec[0:4]
	srSalesRaw := rec[4:12] // 8 chars digits
	// digits only, implied V99
	// If line had shorter raw padded with spaces, those spaces become part of sales digits -> should be treated as spaces? But spec says pad with spaces. For numeric field, spaces would be? In COBOL, numeric field with spaces is zero? However input always provides digits.
	// Trim spaces: if contains spaces, remove spaces or replace with '0'? We'll strip spaces and if empty ->0
	trimmed := strings.TrimSpace(srSalesRaw)
	if trimmed == "" {
		trimmed = "0"
	} else {
		// remove any spaces inside (should not happen)
		trimmed = strings.ReplaceAll(trimmed, " ", "0")
		// Keep only digits, remove non-digits
		var b strings.Builder
		for _, c := range trimmed {
			if c >= '0' && c <= '9' {
				b.WriteRune(c)
			}
		}
		if b.Len() == 0 {
			trimmed = "0"
		} else {
			trimmed = b.String()
		}
	}
	// Now trimmed is digits representing value *100; build decimal with scale 2
	d := mustDecimal(trimmed, 2)
	return SalesRec{SrId: srId, SrSales: d}
}

// ---------- paragraphs ----------

func INITPARA() {
	TierTable[0].TierLimit = mustDecimal("100000", 2) // 1000.00 -> 100000 digits
	TierTable[0].TierRate = mustDecimal("250", 2)     // 2.50 -> 250 with scale 2
	TierTable[1].TierLimit = mustDecimal("500000", 2)
	TierTable[1].TierRate = mustDecimal("400", 2)
	TierTable[2].TierLimit = mustDecimal("2000000", 2)
	TierTable[2].TierRate = mustDecimal("550", 2)
	TierTable[3].TierLimit = mustDecimal("99999999", 2)
	TierTable[3].TierRate = mustDecimal("725", 2)
}

func READPARA() {
	if salesFilePos >= len(salesFileLines) {
		setInputDone(true)
		return
	}
	raw := salesFileLines[salesFilePos]
	salesFilePos++
	SalesRecVar = parseSalesRec(raw)
	// Do not set EOF until next read attempts beyond end
}

func PROCESSPARA() {
	WsTier = 0
	for WsIdx = 1; WsIdx <= 4 && !(WsTier > 0); WsIdx++ {
		limit := TierTable[WsIdx-1].TierLimit
		if SalesRecVar.SrSales.Cmp(limit) <= 0 {
			WsTier = WsIdx
		}
	}
	// COMPUTE WS-COMM ROUNDED = SR-SALES * TIER-RATE /100
	rate := TierTable[WsTier-1].TierRate
	// SR-SALES * rate /100 : do multiply then shift
	prod := SalesRecVar.SrSales.Mul(rate)
	quot := prod.Shift(-2) // divide by 100
	// Rounded to scale 2 (PIC 9(6)V99)
	rounded := quot.Round(2)
	WsComm = storePic9V99(rounded, 6, 2)

	WsTotal = WsTotal.Add(WsComm)
	WsCount++

	WsSalesEd = formatZZEdited(SalesRecVar.SrSales, "ZZZ,ZZ9.99")
	WsRateEd = formatZZEdited(rate, "9.99")
	WsCommEd = formatZZEdited(WsComm, "ZZZ,ZZ9.99")

	// DISPLAY SR-ID " T" WS-TIER " " WS-SALES-ED " " WS-RATE-ED "% " WS-COMM-ED
	// WS-TIER is PIC 9 -> zero padded 1 digit
	tierStr := formatNumericUneditedInt(WsTier, 1)
	line := SalesRecVar.SrId + " T" + tierStr + " " + WsSalesEd + " " + WsRateEd + "% " + WsCommEd
	fmt.Println(line)

	READPARA()
}

func SUMMARYPARA() {
	WsTotalEd = formatZZEdited(WsTotal, "ZZZ,ZZZ,ZZ9.99")
	countStr := formatNumericUneditedInt(WsCount, 3)
	line := "REPS: " + countStr + " TOTAL: " + WsTotalEd
	fmt.Println(line)
}

// ---------- main ----------

func main() {
	INITPARA()
	loadSalesFile()
	READPARA()
	for !isInputDone() {
		PROCESSPARA()
	}
	SUMMARYPARA()
}
